//! Step 3 gate: a short, real streaming LoRA fine-tune against the real
//! 64-layer `Qwen/Qwen3.8-27B-FP8` checkpoint, on the Step 2 dataset
//! (`resources/qwen35_finetune/corpus.txt`, generated by `Qwen/Qwen3-0.6B` -
//! see that file's own sibling `GENERATION.txt` for the exact prompts and
//! sampling settings used). Real per-step cost here is roughly DOUBLE a
//! single M15/M16-class streaming forward pass (a forward+backward step
//! re-streams all 64 layers' weights TWICE, at fp32 rather than int8 - see
//! `qwen35::stream_train`'s own module doc for why fp32) - a handful of
//! steps is the honest, expected scale here, not a production run.
//!
//! `#[ignore]`d, `BRAIN_QWEN35_DIR`-gated - self-skips loudly without it,
//! same convention as every other real-checkpoint test in this crate. Run
//! with:
//!
//! ```text
//! BRAIN_QWEN35_DIR=[path/to/qwen3.8] cargo test -p brain-qwen35 \
//!     --test stream_train_real --release -- --ignored --nocapture --test-threads=1
//! ```
//!
//! This milestone's own reported real numbers were gathered via `src/bin/
//! stream_train_step.rs` instead of a single run of this test binary: the
//! interactive development environment this landed in kills a background
//! process after roughly 45-50 minutes of wall-clock regardless of the
//! `cargo test` timeout requested - shorter than BEFORE-gen (~18 min) plus
//! one real step (~36 min) combined (~54 min), which this single-process
//! test performs twice in the middle of the whole ~106-minute run. The
//! standalone binary splits the SAME `StreamTrainer` calls this test makes
//! into separate short-lived processes, checkpointing the tiny `.lora_a`/
//! `.lora_b` adapter state to a small safetensors file between them
//! (`--phase before|step|after`, `--adapter-in`/`--adapter-out`) - that is
//! an artifact of THIS session's own process-lifetime constraint, not a
//! change to what is being trained or measured (the exact same forward/
//! backward/AdamW calls either way). This test itself is unaffected and
//! remains the way a plain terminal or CI run (no such background-process
//! ceiling) exercises the whole real run in one process.

use std::path::{Path, PathBuf};
use std::time::Instant;

use gpu_core::Gpu;
use qwen35::config::{lora_cfg, Qwen35Config};
use qwen35::model::pipelines;
use qwen35::stream_train::StreamTrainer;

const RANK: u32 = 4;
const ALPHA: f32 = 8.0;
const WINDOW_BUDGET: u32 = 2;
const N_TOKENS: u32 = 16;
const STEPS: u32 = 2;
const LR: f32 = 0.05;
const GEN_PROMPT: &str = "The capital of France is";
const GEN_MAX_NEW: usize = 3;

fn checkpoint_dir() -> Option<PathBuf> {
    std::env::var_os("BRAIN_QWEN35_DIR").map(PathBuf::from)
}

/// Step 2's dataset directory (`GENERATION.txt` + `corpus.txt`) - lives at
/// the WORKSPACE root (a sibling of this repo, not inside it - see M15's
/// own `BRAIN_QWEN35_DIR` convention for real-checkpoint data), so this is
/// resolved from the environment rather than a baked-in absolute path (this
/// repo's own `no-machine-paths-in-crates` pre-commit hook rejects the
/// latter). `None` when unset - the caller skips loudly, same convention as
/// [`checkpoint_dir`].
fn finetune_dataset_dir() -> Option<PathBuf> {
    std::env::var_os("BRAIN_QWEN35_FINETUNE_DIR").map(PathBuf::from)
}

fn tokenizer_path(dir: &Path) -> PathBuf {
    dir.join("tokenizer.json")
}

/// Tokenize `<BRAIN_QWEN35_FINETUNE_DIR>/corpus.txt` (Step 2's dataset) with
/// the REAL checkpoint tokenizer and take the first `N_TOKENS + 1` ids -
/// `[0..N_TOKENS)` as the input, `[1..N_TOKENS+1)` as the shifted next-token
/// target, the standard causal-LM objective at this milestone's own tiny
/// training-sequence scale.
fn training_batch(dir: &Path, dataset_dir: &Path) -> (Vec<u32>, Vec<u32>) {
    let corpus_path = dataset_dir.join("corpus.txt");
    let text = std::fs::read_to_string(&corpus_path)
        .unwrap_or_else(|e| panic!("stream_train_real: read {}: {e} (Step 2's dataset must exist first)", corpus_path.display()));
    let tok = data::qwen_tokenizer::QwenBpe::from_file(tokenizer_path(dir).to_str().unwrap()).unwrap_or_else(|e| panic!("stream_train_real: load tokenizer: {e}"));
    let ids = data::tokenizer::Tokenizer::encode(&tok, &text);
    assert!(ids.len() > N_TOKENS as usize, "stream_train_real: corpus.txt too short ({} tokens, need > {N_TOKENS})", ids.len());
    let input = ids[0..N_TOKENS as usize].to_vec();
    let target = ids[1..(N_TOKENS as usize + 1)].to_vec();
    (input, target)
}

#[test]
#[ignore]
fn short_real_streaming_lora_finetune_reduces_loss_and_shifts_generation() {
    let Some(dir) = checkpoint_dir() else {
        brain_testutil::skip("BRAIN_QWEN35_DIR unset (set it to a downloaded Qwen/Qwen3.8-27B-FP8 dir to run this)");
        return;
    };
    let Some(dataset_dir) = finetune_dataset_dir() else {
        brain_testutil::skip("BRAIN_QWEN35_FINETUNE_DIR unset (set it to the Step 2 dataset dir - GENERATION.txt + corpus.txt - to run this)");
        return;
    };

    let mut cfg = Qwen35Config::qwen38_27b();
    cfg.lora = Some(lora_cfg(RANK, ALPHA));

    let (tokens, targets) = training_batch(&dir, &dataset_dir);
    println!("stream_train_real: training sequence: {} tokens (window_budget={WINDOW_BUDGET}, rank={RANK}, alpha={ALPHA})", tokens.len());

    let lora_init = qwen35::init::init_lora_only(&cfg, 20260820);
    let t0 = Instant::now();
    // CPU JIT backend, not this box's default Vulkan/wgpu adapter: the
    // resident `lm_head`/`embed_tokens` table at fp32 (~4.74 GiB, one
    // contiguous buffer - `Ops::matmul_dx` needs F32/BF16, never int8, see
    // `stream_train`'s own module doc) exceeds this Vulkan adapter's real,
    // measured `max_buffer_size` (2047 MiB - a hard driver/hardware limit,
    // not a host-RAM one; confirmed by an actual `wgpu::Validation Error`
    // on the first attempt at this milestone's own real run, not assumed in
    // advance). The CPU JIT backend has no such per-buffer ceiling (plain
    // host allocations) and, per M13's own profiling, this workload's real
    // cost is dominated by disk I/O + host-side FP8 dequant regardless of
    // which backend runs the matmuls - so running training on CPU here is a
    // genuinely well-justified choice for THIS specific bottleneck, not a
    // downgrade of convenience.
    let trainer = StreamTrainer::new_real(Gpu::new_cpu(pipelines()), &cfg, &dir, N_TOKENS, WINDOW_BUDGET, &lora_init)
        .unwrap_or_else(|e| panic!("stream_train_real: StreamTrainer::new_real: {e}"));
    println!("stream_train_real: trainer construction (resident head+norm load): {:.1}s", t0.elapsed().as_secs_f64());

    let loader = trainer.real_loader(&cfg, &dir);
    let x0 = StreamTrainer::embed_real(&dir, &tokens, cfg.d_model as usize).unwrap_or_else(|e| panic!("stream_train_real: embed_real: {e}"));

    // ---- BEFORE: generate with the fresh (zero-`.lora_b`, exact-no-op) adapter ----
    let tb0 = Instant::now();
    let before = trainer
        .generate_greedy(&cfg, &loader, &dir, &tokenizer_path(&dir), GEN_PROMPT, GEN_MAX_NEW)
        .unwrap_or_else(|e| panic!("stream_train_real: generate_greedy (before): {e}"));
    println!("stream_train_real: BEFORE generation ({:.1} min): {GEN_PROMPT:?} -> {before:?}", tb0.elapsed().as_secs_f64() / 60.0);

    // ---- short real fine-tune ----
    let mut losses = Vec::with_capacity(STEPS as usize);
    for step in 1..=STEPS {
        let ts = Instant::now();
        trainer.lora.zero_grads(&trainer.gpu);
        let loss = trainer.forward_backward(&cfg, &loader, &x0, &targets);
        trainer.lora.adamw_step(&trainer.gpu, step, LR);
        trainer.gpu.poll_wait();
        let secs = ts.elapsed().as_secs_f64();
        println!("stream_train_real: step {step}/{STEPS}: loss={loss:.6} ({:.1} min)", secs / 60.0);
        losses.push(loss);
    }

    // ---- AFTER: generate with the just-trained adapter ----
    let ta0 = Instant::now();
    let after = trainer
        .generate_greedy(&cfg, &loader, &dir, &tokenizer_path(&dir), GEN_PROMPT, GEN_MAX_NEW)
        .unwrap_or_else(|e| panic!("stream_train_real: generate_greedy (after): {e}"));
    println!("stream_train_real: AFTER generation ({:.1} min): {GEN_PROMPT:?} -> {after:?}", ta0.elapsed().as_secs_f64() / 60.0);

    println!("stream_train_real: loss trajectory: {losses:?}");
    println!("stream_train_real: BEFORE: {GEN_PROMPT}{before}");
    println!("stream_train_real: AFTER:  {GEN_PROMPT}{after}");

    assert!(losses[0].is_finite() && losses.last().unwrap().is_finite(), "non-finite loss: {losses:?}");
    assert!(
        losses.last().unwrap() < &losses[0],
        "loss did not decrease over {STEPS} real steps: {losses:?} (this is the gate - report the real numbers either way, do not loosen this silently)"
    );
}
